class Solution {
public:
    std::vector<std::vector<int>> shiftGrid(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        int total = m * n;
        k %= total;
        std::vector<std::vector<int>> res(m, std::vector<int>(n, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                int idx = (r * n + c + k) % total;
                res[idx / n][idx % n] = grid[r][c];
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> shiftGrid(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int total = m * n;
        k %= total;
        int[][] res = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int idx = (r * n + c + k) % total;
                res[idx / n][idx % n] = grid[r][c];
            }
        }
        java.util.List<java.util.List<Integer>> list = new java.util.ArrayList<>();
        for (int r = 0; r < m; r++) {
            java.util.List<Integer> row = new java.util.ArrayList<>();
            for (int c = 0; c < n; c++) row.add(res[r][c]);
            list.add(row);
        }
        return list;
    }
}

var shiftGrid = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const total = m * n;
    k %= total;
    const res = Array.from({ length: m }, () => new Array(n).fill(0));
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const idx = (r * n + c + k) % total;
            res[Math.floor(idx / n)][idx % n] = grid[r][c];
        }
    }
    return res;
};
